// src/<facet>.cpp — the facet's own file; src/main.cpp adds one wiring line:
//   void wire_dash(studio::Game&); wire_dash(game);
#include "studio.h"

namespace {
struct Dash { Vector3 at{}; float cooldown = 0; int dashes = 0; };
Dash dash;
}  // namespace

void wire_dash(studio::Game& game) {
  auto reset = game.reset;
  game.reset = [reset](int seed) {
    if (reset) reset(seed);
    dash = Dash{};
  };
  auto update = game.update;
  game.update = [update](float dt, const studio::Ctx& ctx) {
    if (update) update(dt, ctx);
    dash.cooldown = dash.cooldown > dt ? dash.cooldown - dt : 0;
    if (ctx.keys.pressed("Space") && dash.cooldown == 0) {
      dash.at.x += ctx.rng.nextFloat(2.0f, 3.0f);  // the seeded stream, the same on every destination
      dash.cooldown = 0.5f;
      dash.dashes += 1;
    }
  };
  auto probes = game.probes;
  game.probes = [probes] {
    json::Value out = probes ? probes() : json::Value::object();
    out.set("dashes", dash.dashes);
    return out;
  };
}
